pub mod cache;pub mod pixels;
fn main(){let args:Vec<_>=std::env::args().collect();let n:usize=args[1].parse().unwrap();let mut c=cache::FingerprintCache::default();for i in 0..n{let mut content=[0;32];content[..8].copy_from_slice(&(i as u64).to_le_bytes());c.insert(cache::CacheKey{content,recipe:[2;32],frame_index:3},pixels::Fingerprint{variants:[[123;4];8],mean_linear_rgb:[0.1,0.2,0.3],luminance_stddev:0.4},n).unwrap();}let mut bytes=Vec::new();c.write(&mut bytes,||false).unwrap();let checksum=blake3::hash(&bytes);let calls=std::cell::Cell::new(0u64);let folder=tempfile::tempdir().unwrap();let path=folder.path().join("cache.bin");let start=std::time::Instant::now();for _ in 0..8{c.save_atomic(&path,||{calls.set(calls.get()+1);false}).unwrap();}let elapsed=start.elapsed().as_nanos();let disk=std::fs::read(&path).unwrap();assert_eq!(disk,bytes);cache::FingerprintCache::load_file(&path,n,||false).unwrap();println!("{} {} {} {}",elapsed,calls.get(),bytes.len(),checksum);}
